// RoadCode is s's road code.
func (s Shipment) RoadCode() string { return s.Road }

// WithRoad is s with road code v.
func (s Shipment) WithRoad(v string) Shipment {
	s.Road = v
	return s
}

// RailCode is s's rail code.
func (s Shipment) RailCode() string { return s.Rail }

// WithRail is s with rail code v.
func (s Shipment) WithRail(v string) Shipment {
	s.Rail = v
	return s
}

routes := map[string]string{"road": v}
for r, c := range s.Routes {
	if r != "road" {
		routes[r] = c
	}
}
s.Routes = routes
return s

routes := map[string]string{"rail": v}
for r, c := range s.Routes {
	if r != "rail" {
		routes[r] = c
	}
}
s.Routes = routes
